    public static bool ValidValue(string[]? shape, string kind, string text) => shape?[0] switch
    {
        "System.Boolean" => kind == "Boolean",
        "System.String" => kind == "String",
        "System.Int32" => kind == "Integer" && int.TryParse(text, System.Globalization.NumberStyles.Integer, System.Globalization.CultureInfo.InvariantCulture, out _),
        "System.Int64" => kind == "Integer" && long.TryParse(text, System.Globalization.NumberStyles.Integer, System.Globalization.CultureInfo.InvariantCulture, out _),
        "System.Double" => (kind == "Integer" || kind == "Float") && double.TryParse(text, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out double n) && !double.IsNaN(n) && !double.IsInfinity(n),
        "enum" => kind == "String" && System.Linq.Enumerable.Contains(System.Linq.Enumerable.Skip(shape, 1), text, System.StringComparer.Ordinal),
        "Eplan.EplApi.Base.PointD" => kind == "PointD",
        _ => shape is not null && Kinds(shape[0]).Length > 0 && kind == "locator",
    };
